window.NTI=window.NTI||{};(window.NTI.docs=window.NTI.docs||{})["terraform-03-map-of-the-book"]={"html":"\r\n\r\n\r\n\r\n\r\nTerraform Level 2 · Vol 2 · INK &amp; AMBER\r\n\r\n\r\n\r\n<div class=\"sheet cover\">\r\n  <div class=\"cover-wrap\">\r\n    <div class=\"kick\">TERRAFORM STUDY SERIES · VOLUME TWO</div>\r\n    <div class=\"cover-title\">Level 2 — Advanced IaC</div>\r\n    <div class=\"stamp\">Variables · Outputs · Workspaces · Multi-VPC</div>\r\n    <div class=\"cover-sub\">From one config, many environments. Every variable-passing mechanism, the networking model behind every <code>aws_security_group</code>, workspaces vs folders, count vs for_each, the secrets/outputs contract, and a full end-to-end walkthrough.</div>\r\n    <div class=\"ambrule\"></div>\r\n    <div class=\"credits\">A Technical Book · INK &amp; AMBER Series<br />Course material by <b>Eng. Mohamed Magdy</b><br />Volume I = Level 1 · Volume II = Level 2</div>\r\n    <div class=\"kpills\"><span class=\"kpill\">DAY 1</span><span class=\"kpill amber\">DAY 2 · 3</span><span class=\"kpill\">CAPSTONE</span></div>\r\n    <div class=\"cver\">PRINT-READY · A4 · INTERNAL NAVIGATION</div>\r\n  </div>\r\n</div>\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">CONTENTS</div><h1 id=\"map-of-the-book\">🗺️ Map of the Book</h1></div><span class=\"hmeta\">📖 17 SHEETS</span></div></div>\r\n  <p>Three parts, eight chapters, one capstone. Click any chapter to jump; every page has a <span class=\"backtoc\">TOC</span> badge to come back.</p>\r\n  <div class=\"sec\"><span class=\"n\">I</span>FRONT MATTER</div>\r\n  <div class=\"tocrow\"><span class=\"tocn\">01</span><a href=\"#cover\">Cover &amp; Title</a><span class=\"tocp\">read first</span></div>\r\n  <div class=\"tocrow\"><span class=\"tocn\">02</span><a href=\"#toc\">Contents (this page)</a><span class=\"tocp\">you are here</span></div>\r\n  <div class=\"tocrow\"><span class=\"tocn\">03</span><a href=\"#summary\">Executive Summary</a><span class=\"tocp\">5 min</span></div>\r\n  <div class=\"sec\"><span class=\"n\">II</span>PART I — DAY 1: THE DEEP STACK</div>\r\n  <div class=\"tocrow\"><span class=\"tocn\">04</span><a href=\"#ch-01a\">📦 Variables — precedence, types, validation</a><span class=\"tocp\">⏱ 8 min</span></div>\r\n  <div class=\"tocrow\"><span class=\"tocn\">05</span><a href=\"#ch-01b\">🔧 Functions, dynamic blocks, secrets</a><span class=\"tocp\">⏱ 8 min</span></div>\r\n  <div class=\"tocrow\"><span class=\"tocn\">06</span><a href=\"#ch-02a\">🌐 Networking — protocols, CIDR, routing</a><span class=\"tocp\">⏱ 8 min</span></div>\r\n  <div class=\"tocrow\"><span class=\"tocn\">07</span><a href=\"#ch-02b\">🛡️ SG vs NACL, DNS, endpoints, peering</a><span class=\"tocp\">⏱ 8 min</span></div>\r\n  <div class=\"tocrow\"><span class=\"tocn\">08</span><a href=\"#ch-03a\">🗂️ Workspaces — CLI, patterns, proof</a><span class=\"tocp\">⏱ 7 min</span></div>\r\n  <div class=\"tocrow\"><span class=\"tocn\">09</span><a href=\"#ch-03b\">🏭 Workspaces — CI, sharing, gotchas</a><span class=\"tocp\">⏱ 7 min</span></div>\r\n  <div class=\"sec\"><span class=\"n\">III</span>PART II — DAY 2: SCALING UP</div>\r\n  <div class=\"tocrow\"><span class=\"tocn\">10</span><a href=\"#ch-04a\">🌍 Multi-Env — workspaces vs folders</a><span class=\"tocp\">⏱ 8 min</span></div>\r\n  <div class=\"tocrow\"><span class=\"tocn\">11</span><a href=\"#ch-04b\">🏗️ Multi-VPC — the 3-VPC layout</a><span class=\"tocp\">⏱ 8 min</span></div>\r\n  <div class=\"tocrow\"><span class=\"tocn\">12</span><a href=\"#ch-05\">🔁 count vs for_each — the rename trap</a><span class=\"tocp\">⏱ 8 min</span></div>\r\n  <div class=\"tocrow\"><span class=\"tocn\">13</span><a href=\"#ch-06\">📤 Outputs — the production contract</a><span class=\"tocp\">⏱ 8 min</span></div>\r\n  <div class=\"sec\"><span class=\"n\">IV</span>PART III — DAY 3 &amp; CAPSTONE</div>\r\n  <div class=\"tocrow\"><span class=\"tocn\">15</span><a href=\"#ch-08\">⚖️ ALB Walkthrough — two tiers, one codebase</a><span class=\"tocp\">⏱ 10 min</span></div>\r\n  <div class=\"tocrow\"><span class=\"tocn\">14</span><a href=\"#ch-07\">🚀 End-to-End Project Walkthrough</a><span class=\"tocp\">⏱ 10 min</span></div>\r\n  <div class=\"tocrow\"><span class=\"tocn\">16</span><a href=\"#lab-1\">⭐ Lab 1 — Multi-Env &amp; Multi-VPC Build</a><span class=\"tocp\">⏱ 15 min</span></div>\r\n  <div class=\"sec\"><span class=\"n\">V</span>FINALE</div>\r\n  <div class=\"tocrow\"><span class=\"tocn\">17</span><a href=\"#cheat\">📋 Cheat · Quiz · Glossary · Resources</a><span class=\"tocp\">🏁 end</span></div>\r\n  <div class=\"folio\"><span>Terraform · Vol 2</span><span class=\"fnum\">— Page 2 —</span><span><a href=\"#toc\">TOC</a> prev | <a href=\"#summary\">next</a></span></div>\r\n</div>\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">EXECUTIVE SUMMARY</div><h1 id=\"the-route-one-page-whole-book\">The Route — One Page, Whole Book</h1></div><span class=\"hmeta\">📖 5 MIN</span></div></div>\r\n  <p><b>Level 2</b> takes working single-env code and makes it <b>multi-env, multi-VPC, production-shaped</b>. Prereq: Level 1; everything runs on the local emulator.</p>\r\n  <div class=\"drow\">\r\n    <div class=\"mark m-key\"><span class=\"tag\">🔑 PROBLEM 1</span><b>One code, many envs</b><br />Same HCL drives dev / staging / prod — per-env state, sizing, CIDRs that never overlap.</div>\r\n    <div class=\"mark m-key\"><span class=\"tag\">🔑 PROBLEM 2</span><b>Variables done right</b><br />7-mechanism precedence ladder, type system, validation, sensitive vs ephemeral, 20 key functions.</div>\r\n  </div>\r\n  <div class=\"drow\">\r\n    <div class=\"mark m-key\"><span class=\"tag\">🔑 PROBLEM 3</span><b>Networking that works</b><br />TCP/UDP, CIDR math, route tables, stateful vs stateless, peering, endpoints.</div>\r\n    <div class=\"mark m-key\"><span class=\"tag\">🔑 PROBLEM 4</span><b>Outputs as contract</b><br />Module → stack, stack → stack, sensitive vs ephemeral vs Vault, CI playbook.</div>\r\n  </div>\r\n  <div class=\"sec\"><span class=\"n\">▣</span>One sentence per chapter</div>\r\n  <div class=\"dcol\">\r\n    <div class=\"panel\"><div class=\"ptitle\">📦 Variables</div>Every way to pass a value in — the 7-step ladder, types, validation.</div>\r\n    <div class=\"panel\"><div class=\"ptitle\">🔧 Functions &amp; secrets</div>The 20 functions you'll call, dynamic blocks, Vault/SSM over tfvars secrets.</div>\r\n    <div class=\"panel\"><div class=\"ptitle\">🌐 Networking I</div>TCP/UDP, handshake failures, CIDR math, reserved IPs, routing, tiers.</div>\r\n    <div class=\"panel\"><div class=\"ptitle\">🛡️ Networking II</div>SG vs NACL, DNS flags, endpoints, peering + the silent DNS bug.</div>\r\n    <div class=\"panel\"><div class=\"ptitle\">🗂️ Workspaces</div>One folder, one backend, many state files — CLI, patterns, isolation proof.</div>\r\n    <div class=\"panel\"><div class=\"ptitle\">🏭 Workspaces in prod</div>Decision table, CI with TF_WORKSPACE, sharing, gotchas.</div>\r\n    <div class=\"panel\"><div class=\"ptitle\">🌍 Multi-Env</div>Workspaces vs folders vs buckets — pick by blast radius.</div>\r\n    <div class=\"panel\"><div class=\"ptitle\">🏗️ Multi-VPC</div>The 3-VPC shared/data/apps layout, peering, module scaling.</div>\r\n    <div class=\"panel\"><div class=\"ptitle\">🔁 count vs for_each</div>The rename trap; stable keys win identity; 5 copy-ready patterns.</div>\r\n    <div class=\"panel\"><div class=\"ptitle\">📤 Outputs</div>5 types, sensitive vs ephemeral vs Vault, cross-stack pipelines.</div>\r\n    <div class=\"panel\"><div class=\"ptitle\">🚀 Walkthrough</div>5 files, 3 workspaces, isolation proof, lab checklist.</div>\r\n    <div class=\"panel\"><div class=\"ptitle\">⚖️ ALB Walkthrough</div>Public + internal ALBs, quartet per tier, SG chaining.</div>\r\n    <div class=\"panel\"><div class=\"ptitle\">⭐ Capstone</div>Full multi-env/multi-VPC build, end to end, ready to run.</div>\r\n  </div>\r\n  <div class=\"folio\"><span>Terraform · Vol 2</span><span class=\"fnum\">— Page 3 —</span><span><a href=\"#toc\">TOC</a> <a href=\"#cover\">prev</a> | <a href=\"#ch-01a\">next</a></span></div>\r\n</div>\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART I · DAY 1 · CH 01A</div><h1 id=\"variables-precedence-types-validation\">📦 Variables — Precedence, Types, Validation</h1></div><span class=\"hmeta\">⏱ 8 MIN · VARS</span></div></div>\r\n  <p>Variables are how values get <i>in</i>. Seven mechanisms feed one declaration — later wins. Memorize the ladder, then the types, then validation. Everything downstream consumes this.</p>\r\n  <div class=\"mark m-key\"><span class=\"tag\">🔑 THE LADDER (lowest → highest)</span><b>TF_VAR_* env &lt; terraform.tfvars &lt; *.auto.tfvars (lexical) &lt; -var-file &lt; -var.</b> <code>default</code> is the fallback when nothing provides a value. Prove it once: set all four to different values, plan with <code>-var</code> — CLI wins.</div>\r\n  <div class=\"sec\"><span class=\"n\">§1</span>Passing mechanisms — when each earns its place</div>\r\n  <div class=\"code\"># CLI flags (highest) — envs + one-off tests\r\nterraform apply -var=\"env=prod\" -var=\"count=3\"\r\nterraform apply -var-file=env/prod.tfvars\r\nterraform plan -var=\"env=dev\" -out=tfplan &amp;&amp; terraform apply tfplan\r\n\r\n# Env vars (CI's favorite) — no files, no mounts\r\nexport TF_VAR_env=\"prod\" TF_VAR_count=5\r\n# complex types need HCL syntax: TF_VAR_tags='{\"Env\":\"prod\"}'\r\n# quoting mistakes here are the #1 CI variable bug\r\n\r\n# terraform.tfvars (auto-loaded) — single-dev laptop only\r\nenv = \"dev\"   count = 2   region = \"us-east-1\"\r\n# multi-dev? rename per person + -var-file. NEVER commit secrets:\r\n# commit terraform.tfvars.example, gitignore the real one.\r\n\r\n# *.auto.tfvars (lexical overlay) — base + per-dev layers, no flags\r\n# env/base.auto.tfvars → env/override.auto.tfvars (o wins per key)\r\n# trap: a forgotten *.auto.tfvars silently beats your -var-file</div>\r\n  <div class=\"sec\"><span class=\"n\">§2</span>Type system — declare shape, catch errors at plan</div>\r\n  <div class=\"code\">variable \"env\"     { type = string; default = \"dev\" }\r\nvariable \"count\"   { type = number; default = 1 }\r\nvariable \"enabled\" { type = bool;   default = true }\r\nvariable \"tags\"    { type = map(string);  default = {} }  # NEVER null for maps\r\nvariable \"azs\"     { type = list(string); default = [\"us-east-1a\"] }\r\nvariable \"items\"   { type = set(string);  default = [] }  # for_each, never count\r\nvariable \"server\"  { type = object({ name=string, size=number }) }\r\nvariable \"pair\"    { type = tuple([string, number]) }</div>\r\n  <p>Three underused attributes: <b>sensitive</b> hides CLI output (state still plaintext); <b>nullable = false</b> makes explicit null fall back to default (saves <code>merge()</code>); <b>ephemeral</b> never persists to state — one-shot secrets only.</p>\r\n  <div class=\"sec\"><span class=\"n\">§3</span>Validation — fail at plan, not at 2 AM</div>\r\n  <div class=\"code\">variable \"env\" {\r\n  type = string\r\n  validation { condition = contains([\"dev\",\"staging\",\"prod\"], var.env)\r\n               error_message = \"must be dev/staging/prod\" }\r\n}\r\nvariable \"cidr\" {\r\n  type = string\r\n  validation { condition = can(cidrhost(var.cidr, 0))\r\n               error_message = \"must be a valid CIDR\" }\r\n}</div>\r\n  <p>Multiple <code>validation</code> blocks allowed — all must pass. Split complex rules so the error names the exact problem. Prod rule: required vars (no default) + strict validation; secrets from Vault/SSM, never files.</p>\r\n  <div class=\"folio\"><span>Terraform · Vol 2</span><span class=\"fnum\">— Page 4 —</span><span><a href=\"#toc\">TOC</a> <a href=\"#summary\">prev</a> | <a href=\"#ch-01b\">next</a></span></div>\r\n</div>\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART I · DAY 1 · CH 01B</div><h1 id=\"functions-dynamic-blocks-secrets\">🔧 Functions, Dynamic Blocks, Secrets</h1></div><span class=\"hmeta\">⏱ 8 MIN · VARS II</span></div></div>\r\n  <p>Declarations get values in; <b>functions shape them</b>, <b>dynamic blocks repeat them</b>, and <b>data sources keep secrets out of variables entirely</b>. Test anything here instantly: <code>echo 'format(\"vpc-%s\", var.env)' | terraform console</code>.</p>\r\n  <div class=\"sec\"><span class=\"n\">§1</span>The 20 functions you'll actually call</div>\r\n  <div class=\"dcol3\">\r\n    <div class=\"panel\"><div class=\"ptitle\">String</div><div class=\"code\">format(\"node-%02d-%s\",3,var.env)\r\njoin(\",\", var.azs)\r\nsplit(\",\", \"a,b,c\")\r\nupper(var.env) / lower(var.env)\r\nsubstr(var.project, 0, 8)\r\nreplace(var.name, \"_\", \"-\")\r\ntrimspace(var.input)</div></div>\r\n    <div class=\"panel\"><div class=\"ptitle\">Collection</div><div class=\"code\">merge(var.tags,{Env=var.env})\r\nconcat(var.a, var.b)\r\ndistinct(concat(var.a,var.b))\r\nflatten([[\"a\",\"b\"],[\"c\"]])\r\nkeys(var.amis)/values(var.amis)\r\nlookup(var.amis,var.region,\"fb\")\r\ncontains(var.azs,\"us-east-1a\")\r\nlength(var.azs)</div></div>\r\n    <div class=\"panel\"><div class=\"ptitle\">CIDR &amp; safe</div><div class=\"code\">cidrsubnet(\"10.0.0.0/16\",8,k)\r\ncidrhost(\"10.0.1.0/24\",5)\r\nmax(var.min,2)/min(var.max,10)\r\ntry(var.opt.attr,\"default\")\r\ncan(regex(\"^t[23]\\.\",var.type))\r\ncoalesce(var.a,var.b,\"fb\")\r\none(aws_x.maybe[*].id)</div></div>\r\n  </div>\r\n  <p>Prefer <code>length()</code> / <code>contains()</code> / <code>lookup()</code> with a default over <code>try()</code> — cheaper to read. <code>merge()</code> is shallow (top-level keys only). <code>try()</code> never hides errors outside validation — don't use it to paper over real bugs.</p>\r\n  <div class=\"sec\"><span class=\"n\">§2</span>Dynamic blocks — N rules from one variable</div>\r\n  <div class=\"code\">variable \"ingress_rules\" {\r\n  type = list(object({ desc=string from=number to=number\r\n                       proto=string cidrs=list(string) }))\r\n  default = [\r\n    { desc=\"http\",  from=80,  to=80,  proto=\"tcp\", cidrs=[\"0.0.0.0/0\"] },\r\n    { desc=\"https\", from=443, to=443, proto=\"tcp\", cidrs=[\"0.0.0.0/0\"] } ]\r\n}\r\nresource \"aws_security_group\" \"web\" {\r\n  vpc_id = aws_vpc.main.id\r\n  dynamic \"ingress\" {\r\n    for_each = var.ingress_rules\r\n    content {\r\n      description = ingress.value.desc\r\n      from_port = ingress.value.from   to_port = ingress.value.to\r\n      protocol = ingress.value.proto   cidr_blocks = ingress.value.cidrs\r\n    }\r\n  }\r\n}</div>\r\n  <p>Add a rule = append one object to tfvars, zero HCL edits. Same shape drives ALB listener actions and IAM policy statements.</p>\r\n  <div class=\"sec\"><span class=\"n\">§3</span>Secrets — variables carry the path, never the value</div>\r\n  <div class=\"code\"># SSM (AWS-native, no extra infra)\r\ndata \"aws_ssm_parameter\" \"db_pw\" {\r\n  name = \"/${var.env}/db/password\"   with_decryption = true }\r\nvariable \"db_pw_path\" { default = \"/dev/db/password\" }  # path only!\r\n\r\n# Secrets Manager (rotation-friendly)\r\ndata \"aws_secretsmanager_secret_version\" \"db\" { secret_id = \"prod/db\" }\r\nlocals { db = jsondecode(data.aws_secretsmanager_secret_version.db.secret_string) }\r\n\r\n# Vault (multi-cloud) — same idea via data \"vault_kv_secret_v2\"</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">⚠</span>State holds plaintext regardless — bucket SSE + tight IAM is non-negotiable. CI: pass the secret's <b>path/ARN</b> as the variable; let Terraform read the value at apply time.</div>\r\n  <div class=\"folio\"><span>Terraform · Vol 2</span><span class=\"fnum\">— Page 5 —</span><span><a href=\"#toc\">TOC</a> <a href=\"#ch-01a\">prev</a> | <a href=\"#ch-02a\">next</a></span></div>\r\n</div>\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART I · DAY 1 · CH 02A</div><h1 id=\"networking-protocols-cidr-routing\">🌐 Networking — Protocols, CIDR, Routing</h1></div><span class=\"hmeta\">⏱ 8 MIN · NET I</span></div></div>\r\n  <p>Every AWS resource that takes a CIDR uses one format. Learn TCP/UDP, the handshake failures, CIDR math, and routing once — then every <code>aws_security_group</code> and <code>aws_route_table</code> is syntax.</p>\r\n  <div class=\"mark m-key\"><span class=\"tag\">🔑 DEBUG ORDER</span><b>Route table → SG → NACL.</b> \"Can't reach the internet\" is the route table 80% of the time. Memorize this order before §4.</div>\r\n  <div class=\"sec\"><span class=\"n\">§1</span>TCP vs UDP + the handshake that explains every error</div>\r\n  <div class=\"table-scroll\"><table><tr><th></th><th>TCP</th><th>UDP</th></tr>\r\n  <tr><td>Style</td><td>Connection-oriented, reliable, ordered</td><td>Fire-and-forget, fast, lossy</td></tr>\r\n  <tr><td>Uses</td><td>HTTP/SSH/DB/file transfer</td><td>DNS, video, gaming, VoIP</td></tr>\r\n  <tr><td>Broken</td><td>\"refused\" / timeout / RST</td><td>Silent loss</td></tr>\r\n  <tr><td>Terraform</td><td><code>protocol=\"tcp\"</code></td><td><code>protocol=\"udp\"</code></td></tr></table></div>\r\n  <div class=\"tree\">SYN ──&gt; │ &lt;── SYN-ACK │ ACK ──&gt; │ DATA flows\r\nRST = reached, nothing listening (wrong port / app down)\r\nTIMEOUT = packet dropped (SG deny, NACL deny, route missing)</div>\r\n  <p>Top bug: opening TCP/80 when the server listens on UDP (custom metrics endpoint). Mismatched protocol = silent \"no connection\".</p>\r\n  <div class=\"sec\"><span class=\"n\">§2</span>CIDR math — the only operation that matters</div>\r\n  <div class=\"code\">/32 = 1 IP · /24 = 256 (251 usable) · /16 = 65,536 · /8 = 16M\r\n/16 + 8 newbits = /24 → 2^8 = 256 subnets\r\n/16 + 4 newbits = /20 → 2^4 = 16 subnets\r\nlocals {\r\n  pub  = [for k in range(3) : cidrsubnet(\"10.0.0.0/16\", 8, k)]        # .0 .1 .2\r\n  priv = [for k in range(3) : cidrsubnet(\"10.0.0.0/16\", 8, k + 10)]   # .10 .11 .12\r\n  db   = [for k in range(3) : cidrsubnet(\"10.0.0.0/16\", 8, k + 20)]   # gaps = growth\r\n}</div>\r\n  <p>Reserved per subnet (5): <code>.0</code> network, <code>.1</code> router, <code>.2</code> DNS, <code>.3</code> future, last = broadcast. Pick <code>10.x.0.0/16</code> per env so peered VPCs never overlap.</p>\r\n  <div class=\"sec\"><span class=\"n\">§3</span>Routing — what actually delivers the packet</div>\r\n  <div class=\"code\"># public: everything else → IGW\r\nresource \"aws_route_table\" \"public\" {\r\n  vpc_id = aws_vpc.main.id\r\n  route { cidr_block = \"0.0.0.0/0\"\r\n          gateway_id = aws_internet_gateway.igw.id }\r\n}\r\n# private: everything else → NAT (outbound only)\r\nresource \"aws_route\" \"priv_nat\" {\r\n  route_table_id = aws_route_table.private.id\r\n  destination_cidr_block = \"0.0.0.0/0\"\r\n  nat_gateway_id = aws_nat_gateway.main.id\r\n}</div>\r\n  <p>Longest-prefix match wins. Every subnet uses exactly one route table (explicit or main). SG allows port 80 but no <code>0.0.0.0/0 → igw</code>? Packets go nowhere. Tiers are code, not magic: public = igw route + <code>map_public_ip_on_launch</code>; private = nat route; database = local-only, no default route.</p>\r\n  <div class=\"folio\"><span>Terraform · Vol 2</span><span class=\"fnum\">— Page 6 —</span><span><a href=\"#toc\">TOC</a> <a href=\"#ch-01b\">prev</a> | <a href=\"#ch-02b\">next</a></span></div>\r\n</div>\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART I · DAY 1 · CH 02B</div><h1 id=\"sg-vs-nacl-dns-endpoints-peering\">🛡️ SG vs NACL, DNS, Endpoints, Peering</h1></div><span class=\"hmeta\">⏱ 8 MIN · NET II</span></div></div>\r\n  <p>The #1 interview question lives here: <b>stateful vs stateless</b>. SGs auto-allow return traffic; NACLs need both directions explicit. Then DNS flags, endpoints that skip NAT, and peering's silent DNS bug.</p>\r\n  <div class=\"sec\"><span class=\"n\">§1</span>SG vs NACL — the table to memorize</div>\r\n  <div class=\"table-scroll\"><table><tr><th></th><th>Security Group</th><th>Network ACL</th></tr>\r\n  <tr><td>Level</td><td>Instance / ENI</td><td>Subnet</td></tr>\r\n  <tr><td>Stateful?</td><td><b>Yes</b> — return auto-allowed</td><td><b>No</b> — both directions explicit</td></tr>\r\n  <tr><td>Rules</td><td>Allow only</td><td>Allow + deny (numbered 1–32766)</td></tr>\r\n  <tr><td>Default</td><td>Allow out, deny in</td><td>Allow all both ways</td></tr>\r\n  <tr><td>Use</td><td>Default for everything</td><td>Block a bad IP range; rare</td></tr></table></div>\r\n  <div class=\"code\"># NACL: HTTPS in + EPHEMERAL return (1024-65535) — SG never needs this\r\nresource \"aws_network_acl_rule\" \"https_in\" {\r\n  network_acl_id = aws_network_acl.main.id  rule_number = 100\r\n  egress = false  protocol = \"tcp\"  rule_action = \"allow\"\r\n  cidr_block = \"0.0.0.0/0\"  from_port = 443  to_port = 443\r\n}\r\nresource \"aws_network_acl_rule\" \"ephemeral_out\" {\r\n  network_acl_id = aws_network_acl.main.id  rule_number = 110\r\n  egress = true  protocol = \"tcp\"  rule_action = \"allow\"\r\n  cidr_block = \"0.0.0.0/0\"  from_port = 1024  to_port = 65535\r\n}</div>\r\n  <div class=\"sec\"><span class=\"n\">§2</span>DNS flags + endpoints that skip NAT</div>\r\n  <div class=\"code\">resource \"aws_vpc\" \"main\" {\r\n  cidr_block = \"10.0.0.0/16\"\r\n  enable_dns_support   = true   # .2 resolver in every subnet\r\n  enable_dns_hostnames = true   # public IPs get public DNS names\r\n}\r\n# Gateway endpoint for S3 — FREE, keeps traffic on AWS backbone\r\nresource \"aws_vpc_endpoint\" \"s3\" {\r\n  vpc_id = aws_vpc.main.id\r\n  service_name = \"com.amazonaws.us-east-1.s3\"\r\n  vpc_endpoint_type = \"Gateway\"\r\n  route_table_ids = [aws_route_table.private.id]\r\n}</div>\r\n  <p>DNS off = no discovery, no Route 53 private zones, no <code>nslookup</code> between instances. Endpoints: add lines, save NAT charges, gain latency. Format: <code>com.amazonaws.&lt;region&gt;.&lt;service&gt;</code>.</p>\r\n  <div class=\"sec\"><span class=\"n\">§3</span>Peering + the silent DNS bug</div>\r\n  <div class=\"code\">resource \"aws_vpc_peering_connection\" \"a_to_b\" {\r\n  vpc_id = aws_vpc.a.id  peer_vpc_id = aws_vpc.b.id }\r\n# routes in BOTH tables — peering never auto-propagates\r\nresource \"aws_route\" \"a_to_b\" {\r\n  route_table_id = aws_route_table.a_private.id\r\n  destination_cidr_block = aws_vpc.b.cidr_block\r\n  vpc_peering_connection_id = aws_vpc_peering_connection.a_to_b.id }\r\n# THE SILENT BUG — DNS does NOT cross peering by default:\r\nresource \"aws_vpc_peering_connection_options\" \"a\" {\r\n  vpc_peering_connection_id = aws_vpc_peering_connection.a_to_b.id\r\n  requester { allow_remote_vpc_dns_resolution = true } }\r\n# + mirror block with accepter { ... } on side B</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">⚠</span>Without the flag on <b>both</b> sides: app in A can't resolve private hostnames in B — timeout while SG/route checks pass. Peering is 1:1, no transitive routing; past 3–4 VPCs use Transit Gateway.</div>\r\n  <div class=\"sec\"><span class=\"n\">§4</span>Interview answers</div>\r\n  <ul>\r\n    <li><b>Public vs private — actual difference?</b> Route table (igw vs nat) + <code>map_public_ip_on_launch</code>. Nothing else.</li>\r\n    <li><b>Endpoint vs NAT?</b> NAT = generic egress (paid). Endpoint = one AWS service, cheaper, faster. S3/DynamoDB always via endpoint.</li>\r\n    <li><b>Reserved IPs?</b> 5 per subnet (.0 .1 .2 .3 broadcast). /24 = 251 usable.</li>\r\n  </ul>\r\n  <div class=\"folio\"><span>Terraform · Vol 2</span><span class=\"fnum\">— Page 7 —</span><span><a href=\"#toc\">TOC</a> <a href=\"#ch-02a\">prev</a> | <a href=\"#ch-03a\">next</a></span></div>\r\n</div>\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART I · DAY 1 · CH 03A</div><h1 id=\"workspaces-cli-patterns-proof\">🗂️ Workspaces — CLI, Patterns, Proof</h1></div><span class=\"hmeta\">⏱ 7 MIN · WS I</span></div></div>\r\n  <p>Workspaces are <b>named sub-folders inside one state backend</b>. Same code, same backend, one state file per env. The <code>default</code> workspace is free and implicit — create named ones <b>before the first apply</b>.</p>\r\n  <div class=\"sec\"><span class=\"n\">§1</span>Command reference</div>\r\n  <div class=\"code\">terraform workspace list        # * marks active\r\nterraform workspace new dev     # create + switch (errors if exists)\r\nterraform workspace select prod # switch\r\nterraform workspace show        # prints name only\r\nterraform workspace delete dev  # safe only when state empty\r\nterraform workspace delete dev -force\r\n# → label gone, STATE FILE INTACT on backend. rm the S3 object yourself.\r\n# names: letters digits - _ · no spaces/slashes · default is reserved</div>\r\n  <div class=\"sec\"><span class=\"n\">§2</span>Three in-code patterns via <code>terraform.workspace</code></div>\r\n  <div class=\"code\"># A — sizing per workspace (textbook)\r\nlocals {\r\n  sizing  = { default={count=1,type=\"t3.micro\"} dev={count=1,type=\"t3.micro\"}\r\n              staging={count=2,type=\"t3.small\"} prod={count=3,type=\"t3.small\"} }\r\n  current = local.sizing[terraform.workspace]\r\n}\r\nresource \"aws_instance\" \"cluster\" {\r\n  count = local.current.count   instance_type = local.current.type\r\n  tags  = { Env = terraform.workspace }\r\n}\r\n\r\n# B — common + per-env overlay (lookup default defeats KeyError)\r\nlocals {\r\n  tags = merge({ManagedBy=\"terraform\"},\r\n    lookup({dev={Env=\"dev\"} prod={Env=\"prod\"}}, terraform.workspace,\r\n           {Env=terraform.workspace}))\r\n}\r\n\r\n# C — toggle per workspace\r\nresource \"aws_cloudwatch_log_group\" \"verbose\" {\r\n  count = contains([\"dev\",\"staging\"], terraform.workspace) ? 1 : 0\r\n  retention_in_days = terraform.workspace == \"dev\" ? 1 : 14\r\n}</div>\r\n  <div class=\"sec\"><span class=\"n\">§3</span>Isolation proof — run once, win every argument</div>\r\n  <div class=\"code\">terraform init\r\nterraform workspace new dev     &amp;&amp; terraform apply -auto-approve  # 1×\r\nterraform workspace new staging &amp;&amp; terraform apply -auto-approve  # 2×\r\nterraform workspace new prod    &amp;&amp; terraform apply -auto-approve  # 3×\r\naws s3api list-objects-v2 --bucket tfstate --prefix env/ --query 'Contents[].Key'\r\n# env/dev/terraform.tfstate · env/staging/terraform.tfstate · env/prod/...\r\nterraform workspace select dev &amp;&amp; terraform plan   # → 0/0/0, own state only</div>\r\n  <p>Each workspace's graph knows only its resources. Cross-workspace reads need <code>terraform_remote_state</code> (legacy) or module outputs — workspaces alone share nothing.</p>\r\n  <div class=\"folio\"><span>Terraform · Vol 2</span><span class=\"fnum\">— Page 8 —</span><span><a href=\"#toc\">TOC</a> <a href=\"#ch-02b\">prev</a> | <a href=\"#ch-03b\">next</a></span></div>\r\n</div>\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART I · DAY 1 · CH 03B</div><h1 id=\"workspaces-in-production-ci-sharing-gotchas\">🏭 Workspaces in Production — CI, Sharing, Gotchas</h1></div><span class=\"hmeta\">⏱ 7 MIN · WS II</span></div></div>\r\n  <p>Workspaces are easy to learn, easy to misuse. This page: the decision table, the CI shape that removes human error, cross-workspace sharing, and the 3 gotchas that bite first.</p>\r\n  <div class=\"sec\"><span class=\"n\">§1</span>Workspaces vs folders vs -var-file</div>\r\n  <div class=\"table-scroll\"><table><tr><th></th><th>Workspaces</th><th>Separate folders</th><th>Single -var-file</th></tr>\r\n  <tr><td>State isolation</td><td><span class=\"ok\">Yes, per env</span></td><td><span class=\"ok\">Yes, full blast-radius</span></td><td><span class=\"bad\">No — DANGEROUS</span></td></tr>\r\n  <tr><td>Per-env backends</td><td>No</td><td><span class=\"ok\">Yes (accounts/regions)</span></td><td>N/A</td></tr>\r\n  <tr><td>\"Which env?\"</td><td>Hidden (workspace show)</td><td><span class=\"ok\">Visible (cwd)</span></td><td><span class=\"ok\">Visible (in command)</span></td></tr>\r\n  <tr><td>Locking</td><td>One lock, all envs</td><td>One lock per state</td><td>One lock, all</td></tr>\r\n  <tr><td>Best for</td><td>Solo/small, one account</td><td>Large/regulated, per-account</td><td>Throwaway only</td></tr></table></div>\r\n  <div class=\"sec\"><span class=\"n\">§2</span>CI — never let a human type <code>select prod</code></div>\r\n  <div class=\"code\"># plan dev+staging in parallel on PR; prod only after merge to main\r\nenv: { TF_WORKSPACE: ${{ matrix.env }} }   # pipeline sets it, not fingers\r\nrun: terraform plan -var-file=envs/${{ matrix.env }}.tfvars -out=tfplan\r\n# apply-prod: environment: production (repo approval gate)\r\nenv: { TF_WORKSPACE: prod }\r\nrun: terraform apply -var-file=envs/prod.tfvars tfplan</div>\r\n  <div class=\"sec\"><span class=\"n\">§3</span>Sharing across workspaces</div>\r\n  <div class=\"drow\">\r\n    <div class=\"panel\"><div class=\"ptitle\">A — remote_state (legacy)</div><div class=\"code\">data \"terraform_remote_state\" \"net\" {\r\n  backend = \"s3\"\r\n  config = { bucket=\"tfstate\"\r\n    key=\"env/prod/network/terraform.tfstate\"\r\n    region=\"us-east-1\" } }</div><p>Workspace baked into key; needs bucket IAM. Works, marked legacy.</p></div>\r\n    <div class=\"panel\"><div class=\"ptitle\">B — module output (modern)</div><div class=\"code\">module \"network\" {\r\n  source=\"terraform-aws-modules/vpc/aws\"\r\n  version=\"5.1.0\"  name=\"prod\"\r\n  cidr=\"10.0.0.0/16\" }</div><p>Each workspace provisions its own copy. No cross-state reads.</p></div>\r\n  </div>\r\n  <div class=\"sec\"><span class=\"n\">§4</span>The 3 gotchas</div>\r\n  <div class=\"dcol\">\r\n    <div class=\"qz\"><span class=\"qn\">G1.</span><b>default workspace.</b> First init+apply lands there, unprefixed key. <span class=\"ans\">Fix: workspace new before first apply.</span></div>\r\n    <div class=\"qz\"><span class=\"qn\">G2.</span><b>Shared lock.</b> One table locks all states in the bucket — no parallel applies. <span class=\"ans\">Fix: separate buckets per env.</span></div>\r\n    <div class=\"qz\"><span class=\"qn\">G3.</span><b>Delete keeps state.</b> Label gone, S3 object stays. <span class=\"ans\">Fix: aws s3 rm the key yourself.</span></div>\r\n  </div>\r\n  <div class=\"folio\"><span>Terraform · Vol 2</span><span class=\"fnum\">— Page 9 —</span><span><a href=\"#toc\">TOC</a> <a href=\"#ch-03a\">prev</a> | <a href=\"#ch-04a\">next</a></span></div>\r\n</div>\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART II · DAY 2 · CH 04A</div><h1 id=\"multi-env-workspaces-vs-folders-vs-buckets\">🌍 Multi-Env — Workspaces vs Folders vs Buckets</h1></div><span class=\"hmeta\">⏱ 8 MIN · MENV</span></div></div>\r\n  <p>Three layouts for N envs, one VPC each. Pick by blast radius: solo → workspaces, team → folders, regulated → separate buckets. CIDRs must never overlap — enforce with a matrix in code.</p>\r\n  <div class=\"sec\"><span class=\"n\">§1</span>Layout B1 — workspaces (1 folder, 1 backend, many states)</div>\r\n  <div class=\"code\">locals {\r\n  cidrs = { dev=\"10.0.0.0/16\" staging=\"10.10.0.0/16\" prod=\"10.20.0.0/16\" }\r\n}\r\nresource \"aws_vpc\" \"main\" {\r\n  cidr_block = local.cidrs[terraform.workspace]\r\n  tags = { Env = terraform.workspace }\r\n}\r\n# terraform workspace new dev &amp;&amp; terraform apply  (×3 envs, 3 states, 3 CIDRs)</div>\r\n  <p>Best for solo, single account. Same-bucket blast radius is the price of simplicity.</p>\r\n  <div class=\"sec\"><span class=\"n\">§2</span>Layout B2 — separate folders (1 folder per env)</div>\r\n  <div class=\"code\">envs/dev/main.tf            # no env logic: cidr 10.0.0.0/16, Env=dev\r\nenvs/dev/backend-dev.hcl    # bucket=tfstate key=env/dev/terraform.tfstate\r\nenvs/staging/...  envs/prod/...\r\ncd envs/dev &amp;&amp; terraform init -backend-config=backend-dev.hcl &amp;&amp; terraform apply</div>\r\n  <p>Best for teams: per-env lock, per-env IAM, CI matrix over dirs. A local module kills the duplication (see ch-04b §4).</p>\r\n  <div class=\"sec\"><span class=\"n\">§3</span>Layout B3 — separate buckets (production grade)</div>\r\n  <div class=\"code\"># envs/dev/backend-dev.hcl    → bucket = \"tfstate-dev\"\r\n# envs/prod/backend-prod.hcl  → bucket = \"tfstate-prod\"  (different account)\r\n# Dev apply CANNOT touch the prod bucket (different IAM). Survives audits.</div>\r\n  <div class=\"sec\"><span class=\"n\">§4</span>Decision flowchart</div>\r\n  <div class=\"tree\">1 account · 1 env · study ............ Pattern A (single folder)\r\n1 account · N envs ................. B1 workspaces / B2 folders\r\n1 account · N envs · audit ......... B3 separate buckets\r\nN envs · 2+ VPCs each .............. Pattern C (next page)\r\nN accounts · N envs ................ C3 one account per env\r\n5+ envs · shared config ............ Terragrunt</div>\r\n  <div class=\"folio\"><span>Terraform · Vol 2</span><span class=\"fnum\">— Page 10 —</span><span><a href=\"#toc\">TOC</a> <a href=\"#ch-03b\">prev</a> | <a href=\"#ch-04b\">next</a></span></div>\r\n</div>\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART II · DAY 2 · CH 04B</div><h1 id=\"multi-vpc-the-3-vpc-layout\">🏗️ Multi-VPC — The 3-VPC Layout</h1></div><span class=\"hmeta\">⏱ 8 MIN · MVPC</span></div></div>\r\n  <p>Real orgs run <b>shared + data + apps</b> VPCs per env: ALB/NAT live in shared, RDS/cache in data (no internet), compute in apps. Peered together, isolated at the SG level.</p>\r\n  <div class=\"sec\"><span class=\"n\">§1</span>CIDR matrix — overlap is a plan-time error, not a runtime surprise</div>\r\n  <div class=\"code\">locals {\r\n  cidr_matrix = {\r\n    dev     = { shared=\"10.0.0.0/16\"  data=\"10.1.0.0/16\"  apps=\"10.2.0.0/16\"  }\r\n    staging = { shared=\"10.10.0.0/16\" data=\"10.11.0.0/16\" apps=\"10.12.0.0/16\" }\r\n    prod    = { shared=\"10.20.0.0/16\" data=\"10.21.0.0/16\" apps=\"10.22.0.0/16\" }\r\n  }\r\n  my = local.cidr_matrix[terraform.workspace][var.vpc_role]  # role: shared/data/apps\r\n}\r\nresource \"aws_vpc\" \"this\" {\r\n  cidr_block = local.my_cidr\r\n  tags = { Env = terraform.workspace  Role = var.vpc_role }\r\n}</div>\r\n  <div class=\"sec\"><span class=\"n\">§2</span>Peering + routes — explicit on both sides, no transitive</div>\r\n  <div class=\"code\">resource \"aws_vpc_peering_connection\" \"shared_apps\" {\r\n  vpc_id = aws_vpc.shared.id  peer_vpc_id = aws_vpc.apps.id\r\n  auto_accept = true   # same account; cross-account needs accept_request\r\n  tags = { Pair = \"shared-apps\" }\r\n}\r\nresource \"aws_route\" \"apps_to_shared\" {\r\n  route_table_id = aws_vpc.apps.main_route_table_id\r\n  destination_cidr_block = aws_vpc.shared.cidr_block\r\n  vpc_peering_connection_id = aws_vpc_peering_connection.shared_apps.id\r\n}\r\n# SGs chain by REFERENCE inside a VPC, by CIDR across VPCs:\r\n# apps_ec2 ingress: source = shared_alb.id  (same VPC — never 0.0.0.0/0)</div>\r\n  <div class=\"sec\"><span class=\"n\">§3</span>Scale with a module — 9 lines for the full pattern</div>\r\n  <div class=\"code\"># envs/prod/main.tf — one module block per role, different CIDRs\r\nmodule \"shared\" { source=\"../../modules/vpc-with-peering\"\r\n  cidr=\"10.0.0.0/16\"  role=\"shared\"  az_count=3 }\r\nmodule \"data\"   { source=\"../../modules/vpc-with-peering\"\r\n  cidr=\"10.10.0.0/16\" role=\"data\"    az_count=3 }\r\nmodule \"apps\"   { source=\"../../modules/vpc-with-peering\"\r\n  cidr=\"10.20.0.0/16\" role=\"apps\"    az_count=3 }</div>\r\n  <p>Change the module → every env re-applies (per-state tracking, no cross-env pollution). State layout: <code>s3://tfstate-prod/shared|data|apps/terraform.tfstate</code> — one bad <code>eks/</code> change can't touch <code>data/</code>.</p>\r\n  <div class=\"sec\"><span class=\"n\">§4</span>Gotchas interviews test</div>\r\n  <ul>\r\n    <li><b>Transitive routing doesn't exist.</b> apps→shared→data needs a direct apps→data peering, or TGW.</li>\r\n    <li><b>DNS over peering:</b> <code>allow_remote_vpc_dns_resolution</code> on both sides (ch-02b §3).</li>\r\n    <li><b>SG refs die across VPCs</b> — use CIDR sources cross-VPC, SG refs inside.</li>\r\n    <li><b>State in default workspace</b> — <code>workspace new</code> before first apply, always.</li>\r\n  </ul>\r\n  <div class=\"folio\"><span>Terraform · Vol 2</span><span class=\"fnum\">— Page 11 —</span><span><a href=\"#toc\">TOC</a> <a href=\"#ch-04a\">prev</a> | <a href=\"#ch-05\">next</a></span></div>\r\n</div>\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART II · DAY 2 · CH 05</div><h1 id=\"count-vs-for-each-the-rename-trap\">🔁 count vs for_each — The Rename Trap</h1></div><span class=\"hmeta\">⏱ 8 MIN · META</span></div></div>\r\n  <p>Both copy a resource N times. <b>count = index identity, for_each = key identity.</b> Remove from the middle and count shifts every later copy; for_each kills only the removed key. That's the whole chapter in two sentences — the rest is proof.</p>\r\n  <div class=\"mark m-key\"><span class=\"tag\">🔑 THE RULE</span><b>for_each</b> for anything with a meaningful identity (servers by name, subnets by AZ). <b>count</b> for \"N identical copies\" or 0/1 toggles. Never mix both in one block.</div>\r\n  <div class=\"sec\"><span class=\"n\">§1</span>The difference, demonstrated</div>\r\n  <div class=\"drow\">\r\n    <div class=\"panel\"><div class=\"ptitle\">count — index-based</div><div class=\"code\">resource \"aws_instance\" \"web\" {\r\n  count = 3\r\n  tags = { Name = \"web-${count.index}\" }\r\n}\r\n# → web[0] web[1] web[2]\r\n# count 3→2 destroys web[2].\r\n# Remove the MIDDLE? Later indexes\r\n# SHIFT — downstream refs break.</div></div>\r\n    <div class=\"panel\"><div class=\"ptitle\">for_each — key-based</div><div class=\"code\">resource \"aws_instance\" \"web\" {\r\n  for_each = toset([\"web-a\",\"web-b\"])\r\n  tags = { Name = each.key }\r\n}\r\n# → web[\"web-a\"] web[\"web-b\"]\r\n# Remove \"web-c\": ONLY it dies.\r\n# Rename: old key dies, new key\r\n# born, everything else untouched.</div></div>\r\n  </div>\r\n  <div class=\"sec\"><span class=\"n\">§2</span>5 copy-ready patterns</div>\r\n  <div class=\"code\"># 1 — subnets per AZ (map: AZ → netnum, best of both)\r\nresource \"aws_subnet\" \"public\" {\r\n  for_each = { for i, az in var.azs : az =&gt; i }\r\n  cidr_block = cidrsubnet(\"10.0.0.0/16\", 8, each.value)\r\n  availability_zone = each.key\r\n}\r\n# 2 — IAM users from a list (set: stable identity)\r\nresource \"aws_iam_user\" \"team\" {\r\n  for_each = toset(var.users)   # add \"noor\" → only noor created\r\n  name = each.key\r\n}\r\n# 3 — N identical workers (count earns it here)\r\nresource \"aws_instance\" \"worker\" {\r\n  count = 5\r\n  tags = { Name = \"worker-${count.index}\" }   # 4 destroys worker[4]\r\n}\r\n# 4 — conditional 0/1 + safe read\r\nresource \"aws_cloudwatch_log_group\" \"v\" {\r\n  count = var.enable_monitoring ? 1 : 0 }\r\noutput \"log_group\" { value = one(aws_cloudwatch_log_group.v[*].arn) }\r\n# 5 — for_each needs set/map, never a bare list:\r\n# for_each = toset(var.list)  or  { for x in var.list : x =&gt; x }</div>\r\n  <div class=\"sec\"><span class=\"n\">§3</span>Indexing without the Invalid-index error</div>\r\n  <div class=\"code\">output \"ip_or_null\" { value = try(aws_instance.web[0].public_ip, null) }\r\noutput \"by_name\"     { value = lookup(aws_instance.team, \"ahmed\", null) }</div>\r\n  <p><b>for_each on unknown-at-plan values fails</b> — use count there, or refactor. <code>one()</code> returns the single element or null — perfect for 0/1 resources.</p>\r\n  <div class=\"folio\"><span>Terraform · Vol 2</span><span class=\"fnum\">— Page 12 —</span><span><a href=\"#toc\">TOC</a> <a href=\"#ch-04b\">prev</a> | <a href=\"#ch-06\">next</a></span></div>\r\n</div>\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART II · DAY 2 · CH 06</div><h1 id=\"outputs-the-production-contract\">📤 Outputs — The Production Contract</h1></div><span class=\"hmeta\">⏱ 8 MIN · OUT</span></div></div>\r\n  <p>An <code>output</code> is a <b>named export from state</b> — to modules, other stacks, CI, humans. <code>outputs.tf</code> is the public interface reviewers read first. Five types, one security model, three consumption patterns.</p>\r\n  <div class=\"sec\"><span class=\"n\">§1</span>Anatomy + the 5 types</div>\r\n  <div class=\"code\">output \"vpc_id\" { value = aws_vpc.main.id }   # 1 · scalar\r\noutput \"public_ips\" { value = aws_instance.web[*].public_ip }   # 2 · list\r\noutput \"by_name\" {   # 3 · map (friendliest for curl + downstream)\r\n  value = { for k, inst in aws_instance.web : k =&gt; inst.public_ip } }\r\noutput \"db_password\" {   # 4 · sensitive (CLI-masked, state PLAINTEXT)\r\n  value = aws_db_instance.main.password   sensitive = true }\r\noutput \"deploy_token\" {  # 5 · ephemeral (never in state; same-apply read only)\r\n  value = aws_secretsmanager_secret_version.cur.secret_string\r\n  ephemeral = true }\r\n# + description (always set it) · depends_on (rare) · precondition (underused §3)</div>\r\n  <div class=\"sec\"><span class=\"n\">§2</span>Security model — the interview answer</div>\r\n  <div class=\"table-scroll\"><table><tr><th></th><th>CLI hidden?</th><th>In state?</th><th>Real secrecy?</th></tr>\r\n  <tr><td>Plain</td><td>No</td><td>Yes</td><td><span class=\"bad\">No</span></td></tr>\r\n  <tr><td>sensitive</td><td>Yes (masked)</td><td>Yes, plaintext</td><td><span class=\"bad\">No — masking only</span></td></tr>\r\n  <tr><td>ephemeral</td><td>Yes</td><td>No</td><td>One-shot only</td></tr>\r\n  <tr><td>Vault/SSM/SM</td><td>Via provider</td><td>Encrypted at rest</td><td><span class=\"ok\">Yes — the true story</span></td></tr></table></div>\r\n  <div class=\"sec\"><span class=\"n\">§3</span>Consumption — module, stack, CI</div>\r\n  <div class=\"code\"># module → module (standard):  module.vpc.private_subnets[0]\r\n# stack → stack (legacy remote_state):\r\ndata \"terraform_remote_state\" \"network\" {\r\n  backend = \"s3\"\r\n  config = { bucket=\"tfstate-prod\" key=\"network/terraform.tfstate\" } }\r\n# → data.terraform_remote_state.network.outputs.private_subnet_ids[0]\r\n# source stack MUST run first — CI job graph enforces it.\r\n# CI: terraform output -json | jq -r .vpc_id.value   (mask secrets!)\r\n# plan archaeology: terraform show -json tfplan | jq '.output_changes'</div>\r\n  <div class=\"sec\"><span class=\"n\">§4</span>Guardrails — precondition + naming</div>\r\n  <div class=\"code\">output \"cluster_size\" {\r\n  value = length(aws_instance.cluster)\r\n  precondition { condition = length(aws_instance.cluster) &gt;= 2\r\n    error_message = \"Need ≥2 instances for HA\" }\r\n}</div>\r\n  <p>Name outputs <code>web_instance_ips</code>, not <code>ips</code> — consumers shouldn't guess. Never <code>echo</code> a sensitive output; pipe to a secret store.</p>\r\n  <div class=\"folio\"><span>Terraform · Vol 2</span><span class=\"fnum\">— Page 13 —</span><span><a href=\"#toc\">TOC</a> <a href=\"#ch-05\">prev</a> | <a href=\"#ch-07\">next</a></span></div>\r\n</div>\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART III · DAY 3 · CH 07</div><h1 id=\"end-to-end-project-walkthrough\">🚀 End-to-End Project Walkthrough</h1></div><span class=\"hmeta\">⏱ 10 MIN · E2E</span></div></div>\r\n  <p>Scaffold → code → 3 workspaces → isolation proof. A tiny real cluster: 1 VPC/env, public+private subnets, N instances serving <code>Hello from &lt;env&gt;-&lt;index&gt;</code>. 30 min on the emulator.</p>\r\n  <div class=\"sec\"><span class=\"n\">§1</span>Layout — 5 files, resources apart from providers</div>\r\n  <div class=\"tree\">study-cluster/\r\n├── versions.tf    # pins: TF ≥1.6, aws ~&gt; 5.0 (+ lock file, COMMIT it)\r\n├── variables.tf   # env_override · sizing map · cidrs map (non-overlapping!)\r\n├── providers.tf   # provider blocks, one per cloud\r\n├── main.tf        # VPC → subnets → SG → AMI → instances\r\n└── outputs.tf     # vpc_id · subnets · ips-by-name · count · env</div>\r\n  <div class=\"sec\"><span class=\"n\">§2</span>The core trick — env from workspace, guarded</div>\r\n  <div class=\"code\">locals {\r\n  env_name = var.env_override != \"\" ? var.env_override : terraform.workspace\r\n  effective_env = local.env_name == \"default\" ? \"dev\" : local.env_name\r\n  effective     = var.sizing[local.effective_env]   # {count, type}\r\n  vpc_cidr      = var.cidrs[local.effective_env]    # 10.0 / 10.10 / 10.20\r\n  azs = { for i, az in slice(data.aws_availability_zones.av.names,0,3) : az =&gt; i }\r\n  node_names = [for i in range(local.effective.count) :\r\n                format(\"%s-node-%02d\", local.effective_env, i)]\r\n}\r\nresource \"aws_subnet\" \"public\" {\r\n  for_each = local.azs   # stable identity per AZ\r\n  cidr_block = cidrsubnet(aws_vpc.this.cidr_block, 8, each.value)\r\n  availability_zone = each.key   map_public_ip_on_launch = true\r\n}\r\nresource \"aws_instance\" \"node\" {\r\n  for_each = toset(local.node_names)\r\n  subnet_id = values(aws_subnet.public)[0]   # simplified; prod balances 3\r\n  user_data = &lt;&lt;-EOT\r\n    #!/bin/bash\r\n    apt-get install -y nginx\r\n    echo \"Hello from ${each.key}\" &gt; /var/www/html/index.html\r\n  EOT\r\n}</div>\r\n  <div class=\"sec\"><span class=\"n\">§3</span>Run it — init once, workspace per env, prove isolation</div>\r\n  <div class=\"code\">terraform init   # providers + .terraform.lock.hcl\r\nterraform workspace new dev staging prod   # one command each\r\nterraform workspace select dev &amp;&amp; terraform apply   # 1× → curl: Hello from dev-node-00\r\nterraform workspace select staging &amp;&amp; terraform apply -auto-approve  # 2×\r\nterraform workspace select prod &amp;&amp; terraform apply -auto-approve     # 3×\r\n# PROOF: each env plans clean against its own state:\r\nterraform workspace select dev &amp;&amp; terraform plan  # → 0/0/0\r\n# destroy one env, others untouched: select staging &amp;&amp; terraform destroy</div>\r\n  <p>Remote backend for teams: <code>backend \"s3\"</code> with <code>key = \"study-cluster/terraform.tfstate\"</code> — workspaces prefix <code>env/&lt;name&gt;/</code> automatically. <code>terraform output -json | jq .instance_count.value</code> per env must read 1 / 2 / 3.</p>\r\n  <div class=\"folio\"><span>Terraform · Vol 2</span><span class=\"fnum\">— Page 14 —</span><span><a href=\"#toc\">TOC</a> <a href=\"#ch-06\">prev</a> | <a href=\"#ch-08\">next</a></span></div>\r\n</div>\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART III · DAY 3 · CH 08</div><h1 id=\"alb-walkthrough-two-tiers-one-codebase\">⚖️ ALB Walkthrough — Two Tiers, One Codebase</h1></div><span class=\"hmeta\">⏱ 10 MIN · ALB</span></div></div>\r\n  <p>A public ALB in front of two frontend instances, an internal ALB in front of two backend instances — 18 resources, one <code>main.tf</code>, three envs via workspaces. Every ALB stack is the same <b>quartet</b>: load balancer → target group → listener → attachment.</p>\r\n  <div class=\"sec\"><span class=\"n\">§1</span>The canonical quartet (public tier)</div>\r\n  <div class=\"code\">resource \"aws_lb\" \"public\" {\r\n  name = \"${local.name_prefix}-pub-alb\"\r\n  load_balancer_type = \"application\"\r\n  internal = false   # ← internet-facing; true = internal tier\r\n  security_groups = [aws_security_group.public_alb.id]\r\n  subnets = aws_subnet.public[*].id\r\n}\r\nresource \"aws_lb_target_group\" \"public\" {\r\n  name = \"${local.name_prefix}-pub-tg\"   port = 80\r\n  protocol = \"HTTP\"   target_type = \"instance\"   vpc_id = aws_vpc.this.id\r\n  health_check { path = \"/\"   port = \"traffic-port\"   matcher = \"200\"\r\n    interval = 30   timeout = 5   healthy_threshold = 2   unhealthy_threshold = 3 }\r\n}\r\nresource \"aws_lb_listener\" \"public_http\" {\r\n  load_balancer_arn = aws_lb.public.arn   port = 80   protocol = \"HTTP\"\r\n  default_action { type = \"forward\"\r\n    target_group_arn = aws_lb_target_group.public.arn }\r\n}\r\nresource \"aws_lb_target_group_attachment\" \"public\" {\r\n  count = length(aws_instance.frontend)   # 2 + 2, same count as the fleet\r\n  target_group_arn = aws_lb_target_group.public.arn\r\n  target_id = aws_instance.frontend[count.index].id   port = 80\r\n}</div>\r\n  <p>Internal tier = same quartet with <code>internal = true</code>, swapped SG/subnets/targets. Health-check rule of thumb: <code>interval ≥ 2 × timeout</code>, thresholds summing to 5 for fast convergence.</p>\r\n  <div class=\"sec\"><span class=\"n\">§2</span>SG chaining — ALB → EC2 by reference, never CIDR</div>\r\n  <div class=\"code\"># public_alb: TCP 80/443 from 0.0.0.0/0 (internet-facing)\r\n# frontend_ec2: TCP 80 from public_alb SG ONLY (not 0.0.0.0/0)\r\n# internal_alb: TCP 80 from frontend_ec2 SG + VPC CIDR (defense in depth)\r\n# backend_ec2:  TCP 80 from internal_alb SG ONLY (internal traffic only)\r\ningress { from_port = 80   to_port = 80   protocol = \"tcp\"\r\n  security_groups = [aws_security_group.public_alb.id] }</div>\r\n  <p>SGs referencing each other form a chain Terraform topologically orders — no <code>depends_on</code> needed.</p>\r\n  <div class=\"sec\"><span class=\"n\">§3</span>The elbv2 gotcha + workspace naming</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">⚠</span><code>aws_lb</code> needs the <b>elbv2</b> endpoint — classic <code>elb</code> serves CLBs only. Missing <code>elbv2</code> line = ALB calls silently hit real AWS with emulator creds set. Always redirect <code>ec2, elb, elbv2, iam, sts, s3</code> together via <code>dynamic \"endpoints\"</code> on a null-or-URL variable.</div>\r\n  <div class=\"code\">locals {\r\n  name_prefix = \"${var.project}-${terraform.workspace}\"  # onext-dev-…\r\n  common_tags = { Project = var.project\r\n    Environment = terraform.workspace   ManagedBy = \"terraform\" }\r\n}\r\n# run-alb.sh dev → 22 resources in dev state; staging/prod identical, isolated</div>\r\n  <p>Proof it's correct, not one-shot: re-run <code>plan</code> → <b>No changes</b>. Outputs (<code>public_alb_dns_name</code> + <code>_zone_id</code> for Route53 alias, TG ARNs, instance IDs) feed downstream stacks.</p>\r\n  <div class=\"folio\"><span>Terraform · Vol 2</span><span class=\"fnum\">— Page 15 —</span><span><a href=\"#toc\">TOC</a> <a href=\"#ch-07\">prev</a> | <a href=\"#lab-1\">next</a></span></div>\r\n</div>\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">PART III · CAPSTONE</div><h1 id=\"lab-1-multi-env-amp-multi-vpc-build\">⭐ Lab 1 — Multi-Env &amp; Multi-VPC Build</h1></div><span class=\"hmeta\">⏱ 15 MIN · CAP</span></div></div>\r\n  <p>Stitches every chapter: <b>variables → workspaces → 3-VPC layout → for_each → outputs → destroy</b>. Two tabs — Tab 2 builds, Tab 1 observes. Emulator-ready; same code hits real AWS by deleting endpoints + skip_* lines.</p>\r\n  <div class=\"sec\"><span class=\"n\">▣</span>Build chain (8 resources, one file)</div>\r\n  <div class=\"code\">terraform {\r\n  required_providers { aws = { source = \"hashicorp/aws\", version = \"~&gt; 5.0\" } }\r\n}\r\nprovider \"aws\" {\r\n  region = \"us-east-1\"\r\n  access_key = \"test\"  secret_key = \"test\"   # emulator dummy creds\r\n  skip_credentials_validation = true\r\n  skip_requesting_account_id  = true\r\n  endpoints { ec2 = \"http://localhost:4566\" }   # delete for AWS\r\n}\r\nlocals {\r\n  cidrs = { shared=\"10.0.0.0/16\" data=\"10.10.0.0/16\" apps=\"10.20.0.0/16\" }\r\n}\r\nresource \"aws_vpc\" \"shared\" { cidr_block = local.cidrs.shared\r\n  tags = { Env=terraform.workspace Role=\"shared\" } }\r\nresource \"aws_vpc\" \"data\" { cidr_block = local.cidrs.data\r\n  tags = { Env=terraform.workspace Role=\"data\" } }\r\nresource \"aws_subnet\" \"pub\" {\r\n  for_each = { for i, az in slice(data.aws_availability_zones.av.names,0,2) : az =&gt; i }\r\n  vpc_id = aws_vpc.shared.id\r\n  cidr_block = cidrsubnet(aws_vpc.shared.cidr_block, 8, each.value)\r\n}\r\nresource \"aws_security_group\" \"web\" {\r\n  vpc_id = aws_vpc.shared.id\r\n  ingress { from_port=443 to_port=443 protocol=\"tcp\" cidr_blocks=[\"0.0.0.0/0\"] }\r\n  egress  { from_port=0   to_port=0   protocol=\"-1\"  cidr_blocks=[\"0.0.0.0/0\"] }\r\n}\r\nresource \"aws_instance\" \"web\" {\r\n  for_each = toset([\"a1\",\"a2\",\"b1\",\"b2\"])\r\n  ami = \"ami-0c55b159cbfafe1f0\"   instance_type = \"t3.micro\"\r\n  subnet_id = values(aws_subnet.pub)[0]\r\n}\r\noutput \"ips\" {\r\n  value = { for k, i in aws_instance.web : k =&gt; i.private_ip } }</div>\r\n  <div class=\"sec\"><span class=\"n\">▣</span>Two-terminal execution</div>\r\n  <div class=\"drow\">\r\n    <div class=\"panel\"><div class=\"ptitle\">👀 TAB 1 · OBSERVE</div><div class=\"code\">floci start\r\neval \"$(floci env)\"\r\nwatch aws ec2 describe-vpcs \\\r\n  --query 'Vpcs[].CidrBlock'</div></div>\r\n    <div class=\"panel\"><div class=\"ptitle\">⌨️ TAB 2 · BUILD</div><div class=\"code\">terraform init\r\nterraform workspace new dev\r\nterraform apply -auto-approve\r\nterraform output -json | jq .ips\r\nterraform destroy -auto-approve</div></div>\r\n  </div>\r\n  <div class=\"mark m-exam\"><span class=\"tag\">🎓 WHAT THIS PROVED</span>Provider auth → per-workspace CIDRs → for_each identity → SG → outputs → isolated destroy. Repeat for staging/prod with the matrix from ch-04b.</div>\r\n  <div class=\"folio\"><span>Terraform · Vol 2</span><span class=\"fnum\">— Page 16 —</span><span><a href=\"#toc\">TOC</a> <a href=\"#ch-08\">prev</a> | <a href=\"#cheat\">next</a></span></div>\r\n</div>\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">FINALE</div><h1 id=\"cheat-quiz-glossary-resources\">📋 Cheat · Quiz · Glossary · Resources</h1></div><span class=\"hmeta\">🏁 END</span></div></div>\r\n  <p>The story in one page: commands, quiz, glossary, resources. Tear this page out (mentally) and keep it by your terminal.</p>\r\n  <div class=\"sec\"><span class=\"n\">▣</span>Cheat sheet — the commands</div>\r\n  <div class=\"table-scroll\"><table><tr><th>Command</th><th>What it does</th></tr>\r\n  <tr><td><code>terraform init</code></td><td>Install providers, init backend, lock versions</td></tr>\r\n  <tr><td><code>terraform plan -out=tf</code></td><td>Preview + save (reviewed == executed)</td></tr>\r\n  <tr><td><code>terraform apply tf</code></td><td>Execute exactly the saved plan</td></tr>\r\n  <tr><td><code>terraform output -json</code></td><td>All exports, CI-shaped (| jq .x.value)</td></tr>\r\n  <tr><td><code>workspace new/select/show</code></td><td>Create / switch / print active env</td></tr>\r\n  <tr><td><code>terraform console</code></td><td>REPL — test any function/var instantly</td></tr>\r\n  <tr><td><code>terraform destroy</code></td><td>Tear down THIS workspace only</td></tr></table></div>\r\n  <div class=\"sec\"><span class=\"n\">▣</span>Quiz — 6 questions</div>\r\n  <div class=\"dcol\">\r\n    <div class=\"qz\"><span class=\"qn\">1.</span>Order the ladder: -var, auto.tfvars, tfvars, TF_VAR_, default.<br /><span class=\"ans\">A: -var &gt; -var-file &gt; auto.tfvars &gt; tfvars &gt; TF_VAR_ &gt; default.</span></div>\r\n    <div class=\"qz\"><span class=\"qn\">2.</span>Why does removing a middle count item shift identity?<br /><span class=\"ans\">A: Index-based — later items renumber. for_each keys don't.</span></div>\r\n    <div class=\"qz\"><span class=\"qn\">3.</span>SG allows 443 but curl times out. First check?<br /><span class=\"ans\">A: Route table (0.0.0.0/0 → igw/nat), then NACL ephemeral ports.</span></div>\r\n    <div class=\"qz\"><span class=\"qn\">4.</span>Does sensitive=true encrypt state?<br /><span class=\"ans\">A: No — CLI masking only. State stays plaintext.</span></div>\r\n    <div class=\"qz\"><span class=\"qn\">5.</span>Peering up but cross-VPC DNS fails?<br /><span class=\"ans\">A: allow_remote_vpc_dns_resolution on BOTH sides.</span></div>\r\n    <div class=\"qz\"><span class=\"qn\">6.</span>Deleted workspace — is the state gone?<br /><span class=\"ans\">A: No — label only. rm the S3 key yourself.</span></div>\r\n  </div>\r\n  <div class=\"sec\"><span class=\"n\">▣</span>Glossary — 12 terms</div>\r\n  <div class=\"dcol\">\r\n    <div class=\"glos\"><b>workspace</b> — named state scope under one backend.</div>\r\n    <div class=\"glos\"><b>precedence ladder</b> — CLI &gt; auto.tfvars &gt; tfvars &gt; env &gt; default.</div>\r\n    <div class=\"glos\"><b>validation</b> — plan-time input guard with error_message.</div>\r\n    <div class=\"glos\"><b>dynamic block</b> — N nested blocks from one variable.</div>\r\n    <div class=\"glos\"><b>ephemeral</b> — never persisted; one-shot secrets.</div>\r\n    <div class=\"glos\"><b>longest-prefix match</b> — most specific route wins.</div>\r\n    <div class=\"glos\"><b>stateful / stateless</b> — SG auto-returns; NACL needs both ways.</div>\r\n    <div class=\"glos\"><b>endpoint</b> — private path to one AWS service.</div>\r\n    <div class=\"glos\"><b>rename trap</b> — count re-indexes; for_each keys hold.</div>\r\n    <div class=\"glos\"><b>one()</b> — single-or-null reader for 0/1 resources.</div>\r\n    <div class=\"glos\"><b>precondition</b> — output sanity gate at eval time.</div>\r\n    <div class=\"glos\"><b>TF_WORKSPACE</b> — CI's non-interactive env switch.</div>\r\n  </div>\r\n  <div class=\"sec\"><span class=\"n\">▣</span>Resources — keep these handy</div>\r\n  <div class=\"resbox\"><b>Course deck (this book is built on it):</b> Eng. Mohamed Magdy — Terraform Level 1 + 2<br /><b>Official:</b> <a href=\"https://registry.terraform.io\" target=\"_blank\" rel=\"noopener noreferrer\">registry.terraform.io</a> · <a href=\"https://developer.hashicorp.com/terraform\" target=\"_blank\" rel=\"noopener noreferrer\">developer.hashicorp.com/terraform</a> · <a href=\"https://github.com/hashicorp/terraform\" target=\"_blank\" rel=\"noopener noreferrer\">github.com/hashicorp/terraform</a><br /><b>Learn:</b> <a href=\"https://github.com/hashicorp/learn-terraform\" target=\"_blank\" rel=\"noopener noreferrer\">learn-terraform</a> (free labs) · <a href=\"https://discuss.hashicorp.com/c/terraform-core/\" target=\"_blank\" rel=\"noopener noreferrer\">discuss</a> (forum)<br /><b>Local emulator:</b> <a href=\"https://floci.io\" target=\"_blank\" rel=\"noopener noreferrer\">floci.io</a> (free MIT, port 4566)<br /><b>Exam:</b> HashiCorp Certified — Terraform Associate</div>\r\n  <div class=\"folio\"><span>Terraform · Vol 2</span><span class=\"fnum\">— Page 17 · The End —</span><span><a href=\"#toc\">TOC</a></span></div>\r\n</div>\r\n\r\n","toc":[{"id":"map-of-the-book","text":"🗺️ Map of the Book","level":1},{"id":"the-route-one-page-whole-book","text":"The Route — One Page, Whole Book","level":1},{"id":"variables-precedence-types-validation","text":"📦 Variables — Precedence, Types, Validation","level":1},{"id":"functions-dynamic-blocks-secrets","text":"🔧 Functions, Dynamic Blocks, Secrets","level":1},{"id":"networking-protocols-cidr-routing","text":"🌐 Networking — Protocols, CIDR, Routing","level":1},{"id":"sg-vs-nacl-dns-endpoints-peering","text":"🛡️ SG vs NACL, DNS, Endpoints, Peering","level":1},{"id":"workspaces-cli-patterns-proof","text":"🗂️ Workspaces — CLI, Patterns, Proof","level":1},{"id":"workspaces-in-production-ci-sharing-gotchas","text":"🏭 Workspaces in Production — CI, Sharing, Gotchas","level":1},{"id":"multi-env-workspaces-vs-folders-vs-buckets","text":"🌍 Multi-Env — Workspaces vs Folders vs Buckets","level":1},{"id":"multi-vpc-the-3-vpc-layout","text":"🏗️ Multi-VPC — The 3-VPC Layout","level":1},{"id":"count-vs-for-each-the-rename-trap","text":"🔁 count vs for_each — The Rename Trap","level":1},{"id":"outputs-the-production-contract","text":"📤 Outputs — The Production Contract","level":1},{"id":"end-to-end-project-walkthrough","text":"🚀 End-to-End Project Walkthrough","level":1},{"id":"alb-walkthrough-two-tiers-one-codebase","text":"⚖️ ALB Walkthrough — Two Tiers, One Codebase","level":1},{"id":"lab-1-multi-env-amp-multi-vpc-build","text":"⭐ Lab 1 — Multi-Env &amp; Multi-VPC Build","level":1},{"id":"cheat-quiz-glossary-resources","text":"📋 Cheat · Quiz · Glossary · Resources","level":1}],"words":5626,"assets":[]};